import heapq
from collections import defaultdict

def shortest_path(edges, start, end):
    # Check for negative weights
    for edge in edges:
        if edge[2] < 0:
            raise ValueError("Edge weights cannot be negative.")

    # If start and end are the same
    if start == end:
        return (0, [start])

    # Build the adjacency list
    graph = defaultdict(list)
    nodes = {start, end}
    for u, v, w in edges:
        graph[u].append((v, w))
        nodes.add(u)
        nodes.add(v)

    # If start or end nodes are not in the graph at all
    if start not in nodes or end not in nodes:
        return (None, None)

    # Priority queue stores: (current_distance, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Track the shortest distance to each node to avoid redundant processing
    min_distances = {start: 0}

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # If we reached the destination
        if current_node == end:
            return (current_distance, path)

        # If we found a longer path to the current node already, skip
        if current_distance > min_distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path to the neighbor is found
            if distance < min_distances.get(neighbor, float('inf')):
                min_distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor, path + [neighbor]))

    # If the priority queue empties and we haven't returned, no route exists
    return (None, None)
